Here's a complete, self-contained checkout screen — a `CheckoutScreen.tsx` component plus its `CheckoutScreen.css`, styled to sit naturally inside a Telegram Mini App (using the `--tg-theme-*` CSS variables Telegram injects, with sane fallbacks).

```tsx
// CheckoutScreen.tsx
import React, { useMemo, useState } from "react";
import "./CheckoutScreen.css";

export interface CartItem {
  id: string;
  name: string;
  price: number; // price per unit, in the smallest-displayed currency unit (e.g. dollars)
  quantity: number;
  imageUrl?: string;
}

export interface DeliveryAddress {
  fullName: string;
  phone: string;
  city: string;
  street: string;
  apartment: string;
  postalCode: string;
  comment: string;
}

export interface CheckoutScreenProps {
  items: CartItem[];
  currency?: string;
  initialAddress?: Partial<DeliveryAddress>;
  onBack: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  phone: "",
  city: "",
  street: "",
  apartment: "",
  postalCode: "",
  comment: "",
};

type FieldErrors = Partial<Record<keyof DeliveryAddress, string>>;

const REQUIRED_FIELDS: Array<keyof DeliveryAddress> = [
  "fullName",
  "phone",
  "city",
  "street",
  "postalCode",
];

function formatCurrency(amount: number, currency: string): string {
  try {
    return new Intl.NumberFormat(undefined, {
      style: "currency",
      currency,
      maximumFractionDigits: 2,
    }).format(amount);
  } catch {
    return `${amount.toFixed(2)} ${currency}`;
  }
}

function validate(address: DeliveryAddress): FieldErrors {
  const errors: FieldErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = "Enter your full name";
  }
  if (!address.phone.trim()) {
    errors.phone = "Enter a phone number";
  } else if (!/^[+\d][\d\s()-]{6,}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number";
  }
  if (!address.city.trim()) {
    errors.city = "Enter a city";
  }
  if (!address.street.trim()) {
    errors.street = "Enter a street and house number";
  }
  if (!address.postalCode.trim()) {
    errors.postalCode = "Enter a postal code";
  }

  return errors;
}

export default function CheckoutScreen({
  items,
  currency = "USD",
  initialAddress,
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>({
    ...EMPTY_ADDRESS,
    ...initialAddress,
  });
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const errors = useMemo(() => validate(address), [address]);
  const isValid = useMemo(
    () => REQUIRED_FIELDS.every((field) => !errors[field]),
    [errors]
  );

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const itemCount = useMemo(
    () => items.reduce((sum, item) => sum + item.quantity, 0),
    [items]
  );

  function handleChange(field: keyof DeliveryAddress) {
    return (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      setAddress((prev) => ({ ...prev, [field]: e.target.value }));
    };
  }

  function handleBlur(field: keyof DeliveryAddress) {
    return () => setTouched((prev) => ({ ...prev, [field]: true }));
  }

  async function handlePay() {
    setTouched(
      REQUIRED_FIELDS.reduce((acc, field) => ({ ...acc, [field]: true }), {})
    );

    if (!isValid || items.length === 0) return;

    setSubmitError(null);
    setIsSubmitting(true);
    try {
      await onPay(address);
    } catch (err) {
      setSubmitError(
        err instanceof Error ? err.message : "Payment failed. Please try again."
      );
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <div className="checkout">
      <header className="checkout__header">
        <button
          type="button"
          className="checkout__back"
          onClick={onBack}
          aria-label="Back to cart"
        >
          <svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true">
            <path
              d="M15 18l-6-6 6-6"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
        <h1 className="checkout__title">Checkout</h1>
        <span className="checkout__header-spacer" aria-hidden="true" />
      </header>

      <div className="checkout__content">
        <section className="checkout__section" aria-labelledby="order-heading">
          <h2 id="order-heading" className="checkout__section-title">
            Your order
          </h2>

          {items.length === 0 ? (
            <p className="checkout__empty">Your cart is empty.</p>
          ) : (
            <ul className="checkout__items">
              {items.map((item) => (
                <li key={item.id} className="checkout-item">
                  <div className="checkout-item__thumb">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt="" />
                    ) : (
                      <span className="checkout-item__thumb-fallback">
                        {item.name.charAt(0).toUpperCase()}
                      </span>
                    )}
                  </div>
                  <div className="checkout-item__info">
                    <span className="checkout-item__name">{item.name}</span>
                    <span className="checkout-item__meta">
                      {item.quantity} × {formatCurrency(item.price, currency)}
                    </span>
                  </div>
                  <span className="checkout-item__subtotal">
                    {formatCurrency(item.price * item.quantity, currency)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="checkout__totals">
            <div className="checkout__totals-row">
              <span>
                Subtotal · {itemCount} {itemCount === 1 ? "item" : "items"}
              </span>
              <span>{formatCurrency(subtotal, currency)}</span>
            </div>
            <div className="checkout__totals-row checkout__totals-row--grand">
              <span>Total</span>
              <span>{formatCurrency(subtotal, currency)}</span>
            </div>
          </div>
        </section>

        <section className="checkout__section" aria-labelledby="address-heading">
          <h2 id="address-heading" className="checkout__section-title">
            Delivery address
          </h2>

          <form className="checkout-form" noValidate>
            <div className="checkout-form__field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                autoComplete="name"
                value={address.fullName}
                onChange={handleChange("fullName")}
                onBlur={handleBlur("fullName")}
                aria-invalid={Boolean(touched.fullName && errors.fullName)}
              />
              {touched.fullName && errors.fullName && (
                <span className="checkout-form__error">{errors.fullName}</span>
              )}
            </div>

            <div className="checkout-form__field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                autoComplete="tel"
                value={address.phone}
                onChange={handleChange("phone")}
                onBlur={handleBlur("phone")}
                aria-invalid={Boolean(touched.phone && errors.phone)}
              />
              {touched.phone && errors.phone && (
                <span className="checkout-form__error">{errors.phone}</span>
              )}
            </div>

            <div className="checkout-form__row">
              <div className="checkout-form__field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  autoComplete="address-level2"
                  value={address.city}
                  onChange={handleChange("city")}
                  onBlur={handleBlur("city")}
                  aria-invalid={Boolean(touched.city && errors.city)}
                />
                {touched.city && errors.city && (
                  <span className="checkout-form__error">{errors.city}</span>
                )}
              </div>

              <div className="checkout-form__field checkout-form__field--narrow">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  autoComplete="postal-code"
                  value={address.postalCode}
                  onChange={handleChange("postalCode")}
                  onBlur={handleBlur("postalCode")}
                  aria-invalid={Boolean(touched.postalCode && errors.postalCode)}
                />
                {touched.postalCode && errors.postalCode && (
                  <span className="checkout-form__error">{errors.postalCode}</span>
                )}
              </div>
            </div>

            <div className="checkout-form__field">
              <label htmlFor="street">Street and house number</label>
              <input
                id="street"
                type="text"
                autoComplete="address-line1"
                value={address.street}
                onChange={handleChange("street")}
                onBlur={handleBlur("street")}
                aria-invalid={Boolean(touched.street && errors.street)}
              />
              {touched.street && errors.street && (
                <span className="checkout-form__error">{errors.street}</span>
              )}
            </div>

            <div className="checkout-form__field">
              <label htmlFor="apartment">
                Apartment / unit <span className="checkout-form__optional">(optional)</span>
              </label>
              <input
                id="apartment"
                type="text"
                autoComplete="address-line2"
                value={address.apartment}
                onChange={handleChange("apartment")}
              />
            </div>

            <div className="checkout-form__field">
              <label htmlFor="comment">
                Comment for courier <span className="checkout-form__optional">(optional)</span>
              </label>
              <textarea
                id="comment"
                rows={3}
                value={address.comment}
                onChange={handleChange("comment")}
              />
            </div>
          </form>
        </section>
      </div>

      <footer className="checkout__footer">
        {submitError && <p className="checkout__submit-error">{submitError}</p>}
        <button
          type="button"
          className="checkout__pay-button"
          onClick={handlePay}
          disabled={items.length === 0 || isSubmitting}
        >
          {isSubmitting
            ? "Processing…"
            : `Pay ${formatCurrency(subtotal, currency)}`}
        </button>
      </footer>
    </div>
  );
}
```

